function guessPackagingMatch(unitRaw, item) {
  if (!item) return null;
  const u = String(unitRaw || "").toLowerCase().trim();
  if (!u) return null;
  return (item.packagings || []).find((p) => u.includes(p.label.toLowerCase()) || p.label.toLowerCase().includes(u)) || null;
}

function guessConvFactor(unitRaw, item) {
  if (!item) return 1;
  const u = String(unitRaw || "").toLowerCase().trim();
  const base = item.baseUnitLabel.toLowerCase();
  if (!u || u === base) return 1;
  if (u.includes("kg") && base.includes("gram")) return 1000;
  if (u.includes("ons") && base.includes("gram")) return 100;
  const pack = guessPackagingMatch(u, item);
  if (pack) return pack.qtyBase;
  return 1;
}

