function guessItemMatch(name, items) {
  const n = String(name || "").toLowerCase();
  if (!n) return null;
  let found = items.find((it) => it.name.toLowerCase() === n);
  if (found) return found;
  found = items.find((it) => n.includes(it.name.toLowerCase()) || it.name.toLowerCase().includes(n));
  return found || null;
}

