// Menghitung ulang SEMUA biaya job costing secara berurutan (dari tanggal paling lama),
// supaya biaya bahan yang berasal dari hasil produksi batch sebelumnya (misal semi jadi
// yang dipakai lagi jadi bahan produk lain) ikut ter-update rantai biayanya, bukan
// memakai angka lama yang sudah dibekukan sejak batch itu pertama kali disimpan.
function recalculateAllJobCostings(data) {
  const sumBase = {};
  const sumCost = {};
  data.purchases.forEach((p) => {
    p.items.forEach((li) => {
      if (li.purchaseType === "biaya") return;
      sumBase[li.itemId] = (sumBase[li.itemId] || 0) + li.qtyBase;
      sumCost[li.itemId] = (sumCost[li.itemId] || 0) + li.qtyBase * (li.unitPrice || 0);
    });
  });
  function currentAvgCost(itemId) {
    return sumBase[itemId] > 0 ? sumCost[itemId] / sumBase[itemId] : 0;
  }

  const sorted = [...data.jobCostings].sort((a, b) => (a.date === b.date ? (a.createdAt || 0) - (b.createdAt || 0) : a.date.localeCompare(b.date)));

  const updatedById = {};
  sorted.forEach((j) => {
    const newBahanBaku = j.bahanBaku.map((b) => {
      const unitCost = currentAvgCost(b.itemId);
      const lineCost = b.qtyBase * unitCost;
      const waste = b.expectedQtyBase != null ? lineCost - b.expectedQtyBase * unitCost : null;
      return { ...b, unitCost, lineCost, waste };
    });
    const totalCost = newBahanBaku.reduce((s, b) => s + b.lineCost, 0);
    const totalWaste = newBahanBaku.reduce((s, b) => s + (b.waste || 0), 0);

    const items = data.items;
    const hasilRows = j.hasil.map((h) => ({ ...h, item: items.find((i) => i.id === h.itemId) }));
    // Destructure `item` keluar — objek item lengkap tidak boleh ikut tersimpan ke storage.
    const newHasil = allocateHasilCostsByRecipe(hasilRows, totalCost, currentAvgCost).map((r) => {
      const { item, ...rest } = r;
      return rest;
    });
    const jobTotalOutputBase = newHasil.reduce((s, h) => s + h.qtyBase, 0);
    const costPerBaseUnit = jobTotalOutputBase > 0 ? totalCost / jobTotalOutputBase : 0;
    const costPerUnitLabel = newHasil.length === 1 ? newHasil[0].costPerUnitLabel : "";

    updatedById[j.id] = { ...j, bahanBaku: newBahanBaku, hasil: newHasil, totalCost, totalWaste, costPerBaseUnit, costPerUnitLabel };

    // Hasil batch ini langsung dipakai untuk update biaya rata-rata berjalan,
    // supaya batch SETELAHNYA yang pakai item ini sebagai bahan dapat harga yang sudah benar.
    newHasil.forEach((h) => {
      if (!h.qtyBase) return;
      sumBase[h.itemId] = (sumBase[h.itemId] || 0) + h.qtyBase;
      sumCost[h.itemId] = (sumCost[h.itemId] || 0) + (h.allocatedCost || 0);
    });
  });

  return data.jobCostings.map((j) => updatedById[j.id] || j);
}

// Setiap perubahan pembelian atau resep menggeser biaya/bobot alokasi, sehingga HPP seluruh batch
// job costing sesudahnya ikut bergeser — termasuk batch yang memakai semi jadi dari batch
// sebelumnya. Bungkus perubahan itu dengan fungsi ini supaya rantainya langsung terhitung ulang,
// bukan menunggu seseorang ingat menekan tombol hitung ulang di tab Job Costing.
function withRecalcJobCostings(nextData) {
  return { ...nextData, jobCostings: recalculateAllJobCostings(nextData) };
}

function exportSuratJalanExcelRows(filteredRows) {
  const rows = filteredRows.map((li) => ({
    Tanggal: li.date,
    "No. SJ": li.nomor,
    "No. PO": li.noPO || "-",
    Toko: li.storeName || "-",
    Produk: li.itemName,
    Jumlah: li.qtyPack,
    Satuan: li.unit || "",
    Keterangan: li.note || "",
  }));
  const ws = XLSX.utils.json_to_sheet(rows.length ? rows : [{ Tanggal: "-" }]);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Surat Jalan");
  XLSX.writeFile(wb, `laporan-surat-jalan-${todayStr()}.xlsx`);
}

